//! Resident bounded JSON-line runtime over stdin/stdout; no network exposure.
use crate::{engine::Engine,indexed::Result,dataflow,plan};
use serde::{Deserialize,Serialize};
use std::io::{BufRead,Read,Write};
use crate::diagnostics::Metrics;
#[derive(Deserialize)]#[serde(tag="kind",rename_all="snake_case",deny_unknown_fields)]enum Request{Ask{question:String},Plan{plan:plan::Plan},Dataflow{program:dataflow::Program},Health,Metrics}
#[derive(Serialize)]struct Reply{ok:bool,result:Option<serde_json::Value>,error:Option<String>}
pub fn dispatch(e:&Engine<'_>,raw:&str)->Result<serde_json::Value>{if raw.len()>65536{return Err("request limit".into())}match serde_json::from_str::<Request>(raw)?{Request::Ask{question}=>{let r=e.ask(&question)?;Ok(serde_json::json!({"text":r.text,"path":r.path,"complete":r.complete,"model_called":r.model_called}))},Request::Plan{plan:p}=>Ok(serde_json::to_value(plan::execute(e,&p)?)?),Request::Dataflow{program:p}=>Ok(serde_json::to_value(dataflow::execute(e,&p)?)?),Request::Health=>Ok(serde_json::json!({"status":"ready","protocol":1})),Request::Metrics=>Err("metrics requires resident session".into())}}
pub fn serve(e:&Engine<'_>,mut input:impl BufRead,mut output:impl Write)->Result<()>{let mut metrics=Metrics::default();let predictor=if std::env::var("AIR_PREDICTIVE").as_deref()==Ok("1"){Some(crate::prediction::Predictor::open(&e.policy.path)?)}else{None};let mut previous:Option<String>=None;loop{let mut line=String::new();let n=Read::take(&mut input,65537).read_line(&mut line)?;if n==0{return Ok(())}if n>65536{return Err("request too large".into())}let start=std::time::Instant::now();if let (Some(p),Ok(Request::Ask{question}))=(&predictor,serde_json::from_str::<Request>(&line)){let category=match crate::router::deterministic(&question){crate::router::Route::Category{category}=>Some(category),_=>None};if let Some(c)=category{if c.len()<=256&&e.knowledge.has_category(&c).unwrap_or(false){if let Some(old)=&previous{let _=p.observe(old,&c);}if let Ok(w)=crate::prefetch::warm(e.knowledge,p,&c,2,256*1024){metrics.prefetch_categories=metrics.prefetch_categories.saturating_add(w.categories as u64);metrics.prefetch_bytes=metrics.prefetch_bytes.saturating_add(w.payload_bytes as u64);}previous=Some(c);}}}let reply=if matches!(serde_json::from_str::<Request>(&line),Ok(Request::Metrics)){Reply{ok:true,result:Some(serde_json::to_value(&metrics)?),error:None}}else{metrics.requests=metrics.requests.saturating_add(1);match dispatch(e,&line){Ok(v)=>{if v["model_called"]==true{metrics.model_calls=metrics.model_calls.saturating_add(1);}if v["complete"]==true{metrics.completed=metrics.completed.saturating_add(1);}Reply{ok:true,result:Some(v),error:None}},Err(_)=>{metrics.errors=metrics.errors.saturating_add(1);Reply{ok:false,result:None,error:Some("invalid or failed request".into())}}}};metrics.elapsed_ns=metrics.elapsed_ns.saturating_add(start.elapsed().as_nanos());serde_json::to_writer(&mut output,&reply)?;output.write_all(b"\n")?;output.flush()?;}}
